import React from "react"

/**
 * Toggle — a switch built on a real checkbox input.
 *
 * The CSS depends on .toggle__input being the immediate previous sibling of
 * .toggle__track, so the DOM order here must not change.
 *
 * Props: { checked, onChange, label, id, disabled, ariaLabel }
 */

function noop() {}

function Toggle({ checked = false, onChange, label, id, disabled = false, ariaLabel }) {
  const handleChange = typeof onChange === "function" ? onChange : noop
  const fallbackLabel = label ? undefined : ariaLabel || "Toggle"

  return (
    <label className="toggle" htmlFor={id}>
      <input
        className="toggle__input"
        type="checkbox"
        id={id}
        checked={!!checked}
        disabled={!!disabled}
        onChange={handleChange}
        aria-label={fallbackLabel}
      />
      <span className="toggle__track">
        <span className="toggle__thumb" />
      </span>
      {label ? <span className="toggle__label">{label}</span> : null}
    </label>
  )
}

export default Toggle
