import React from "react"
import Icon from "./Icon"

/**
 * MetricCard — a compact metric panel.
 *
 * One figure dominates; everything else is support. The card is deliberately
 * short: a 1px border, no shadow, tight padding. Structure comes from the
 * border and the internal rhythm, not from elevation.
 *
 * `trend` is a NODE, not data — the caller passes an already-built <Sparkline>
 * so this component never has to know about chart shapes or window lengths.
 */

const ICON_TONES = { accent: true, up: true, down: true }
// The bar's default fill is the accent, so only direction earns a modifier.
const BAR_TONES = { up: true, down: true }

function iconTone(tone) {
  return ICON_TONES[tone] ? " metric__icon--" + tone : ""
}

function barTone(tone) {
  return BAR_TONES[tone] ? " metric__bar-fill--" + tone : ""
}

function clampPercent(value) {
  if (!Number.isFinite(value)) return null
  return Math.max(0, Math.min(100, value))
}

export default function MetricCard({
  label,
  value,
  unit,
  meta,
  icon,
  tone = "neutral",
  bar = null,
  trend = null,
  footnote,
}) {
  const width = bar === null || bar === undefined ? null : clampPercent(Number(bar))

  return (
    <article className="metric">
      <div className="metric__head">
        {icon && (
          <span className={"metric__icon" + iconTone(tone)}>
            <Icon name={icon} size={14} />
          </span>
        )}
        <span className="metric__label">{label}</span>
      </div>

      <div className="metric__body">
        <span className="metric__value">{value}</span>
        {unit && <span className="metric__unit">{unit}</span>}
        {meta && <span className="metric__meta">{meta}</span>}
      </div>

      {width !== null && (
        <div className="metric__bar">
          <div
            className={"metric__bar-fill" + barTone(tone)}
            style={{ width: width + "%" }}
          />
        </div>
      )}

      {trend && <div className="metric__trend">{trend}</div>}

      {footnote && <p className="metric__footnote">{footnote}</p>}
    </article>
  )
}
