import React, { useEffect, useState } from "react"

/**
 * TickerMark — a square company mark for a ticker symbol.
 *
 * Colour resolution happens entirely in CSS: the background is
 *   var(--brand-AAPL, var(--mark-3))
 * so tokens.css decides whether a curated brand colour exists and otherwise
 * falls back to a deterministic slot in the --mark-1 .. --mark-8 palette.
 * The inline style object carries custom properties only — never a literal colour.
 *
 * The logo PNG cannot be probed at build time, so the server-rendered markup is
 * always the letter fallback. A browser-only useEffect pre-loads /logos/{SLUG}.png
 * and swaps in the image only once it has genuinely loaded, which keeps the
 * no-logo case completely flicker-free.
 */

const PALETTE_SIZE = 8
const BULLET = "\u2022"

function normaliseSymbol(symbol) {
  return String(symbol || "")
    .trim()
    .toUpperCase()
}

function toSlug(symbol) {
  let slug = ""
  for (let i = 0; i < symbol.length; i += 1) {
    const ch = symbol.charAt(i)
    slug += ch >= "A" && ch <= "Z" ? ch : ch >= "0" && ch <= "9" ? ch : "-"
  }
  return slug
}

function markIndex(symbol) {
  let hash = 0
  for (let i = 0; i < symbol.length; i += 1) {
    hash = (hash * 31 + symbol.charCodeAt(i)) % 1000003
  }
  return (hash % PALETTE_SIZE) + 1
}

function TickerMark({ symbol, size = 32, className }) {
  const sym = normaliseSymbol(symbol)
  const slug = toSlug(sym)
  const colourSlug = slug || "UNKNOWN"
  const [logo, setLogo] = useState(null)

  /*
   * Real logos live in /static/logos/{SYMBOL}.{svg|png}, fetched once by
   * scripts/fetch-logos.mjs and committed, so the running app never makes a
   * network call. The filesystem cannot be probed during Gatsby's Node render,
   * so the server always emits the letter mark and the browser swaps in a real
   * logo only after one genuinely loads — which keeps the no-logo case
   * completely flicker-free.
   */
  useEffect(() => {
    setLogo(null)
    if (!slug) return undefined

    let cancelled = false
    const candidates = ["svg", "png"]
    const probes = []

    candidates.forEach((ext, index) => {
      const probe = new window.Image()
      probes.push(probe)
      probe.onload = function handleLoad() {
        // Prefer the earliest candidate that resolves, so a late-arriving PNG
        // never displaces an SVG that already loaded.
        if (cancelled) return
        setLogo(current => (current && current.index <= index ? current : { index, ext }))
      }
      probe.onerror = function handleError() {
        // No asset at this extension — the letter fallback stands.
      }
      probe.src = "/logos/" + slug + "." + ext
    })

    return function cleanup() {
      cancelled = true
      for (const probe of probes) {
        probe.onload = null
        probe.onerror = null
      }
    }
  }, [slug])

  const style = logo
    ? { "--mark-size": size + "px" }
    : {
        "--mark-size": size + "px",
        background: "var(--brand-" + colourSlug + ", var(--mark-" + markIndex(sym) + "))",
      }
  const classes = [
    "ticker-mark",
    logo ? "ticker-mark--logo" : null,
    className,
  ]
    .filter(Boolean)
    .join(" ")
  const letter = sym.charAt(0) || BULLET

  return (
    <span
      className={classes}
      style={style}
      role="img"
      aria-label={sym || "Unknown ticker"}
    >
      {logo ? (
        <img
          className="ticker-mark__image"
          src={"/logos/" + colourSlug + "." + logo.ext}
          alt=""
        />
      ) : (
        <span className="ticker-mark__letter" aria-hidden="true">
          {letter}
        </span>
      )}
    </span>
  )
}

export default TickerMark
