import React from "react"

/**
 * SignalBadge — the rating a symbol carries, rendered as a real component
 * rather than a decorative tag.
 *
 * The five states must be told apart WITHOUT colour, so each one carries three
 * redundant cues: a distinct glyph, the written label, and — when supplied —
 * the numeric score. Colour is the fourth cue, never the only one. The glyph is
 * aria-hidden because the visible label already states the rating in words.
 *
 * `reason` (from getSignalScore) becomes the title, so hovering explains why
 * the rating reads the way it does.
 */

const MARKS = {
  "strong-buy": "\u25B2\u25B2",
  buy: "\u25B2",
  neutral: "=",
  reduce: "\u25BC",
  sell: "\u25BC\u25BC",
}

const LABELS = {
  "strong-buy": "Strong buy",
  buy: "Buy",
  neutral: "Neutral",
  reduce: "Reduce",
  sell: "Sell",
}

/**
 * "Strong buy" -> "strong-buy". Anything unrecognised falls back to neutral so
 * a bad input can never render an unstyled badge.
 */
function toState(signal) {
  const key = String(signal ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-")
  return MARKS[key] ? key : "neutral"
}

export default function SignalBadge({
  signal,
  score,
  confidence,
  reason,
  size,
  showScore = true,
  className,
}) {
  const state = toState(signal)
  const label = LABELS[state]
  const hasScore = showScore && typeof score === "number" && Number.isFinite(score)
  const rounded = hasScore ? Math.round(score) : null

  const classes = [
    "signal-badge",
    "signal-badge--" + state,
    size === "sm" ? "signal-badge--sm" : null,
    size === "lg" ? "signal-badge--lg" : null,
    className,
  ]
    .filter(Boolean)
    .join(" ")

  return (
    <span className={classes} title={reason || undefined}>
      <span className="signal-badge__mark" aria-hidden="true">
        {MARKS[state]}
      </span>
      <span className="signal-badge__label">{label}</span>
      {hasScore && (
        <span className="signal-badge__score">
          <span className="u-visually-hidden">, score </span>
          {rounded}
          <span className="u-visually-hidden"> of 100</span>
        </span>
      )}
      {confidence && (
        <span className="signal-badge__confidence">
          <span className="u-visually-hidden">, </span>
          {confidence}
          <span className="u-visually-hidden"> confidence</span>
        </span>
      )}
    </span>
  )
}
