import React, { useId } from "react"

/**
 * Select — a native select with a custom chevron.
 *
 * Props:
 *   label    optional visible label
 *   value    controlled value (falls back to the first option)
 *   onChange native change handler; receives the event
 *   options  array of strings, or of { label, value }
 *   id       optional id; a stable SSR-safe one is generated with useId()
 *   name     optional form name
 */

function noop() {}

function normaliseOptions(options) {
  if (!Array.isArray(options)) return []
  return options.filter(option => option !== null && option !== undefined).map(option => {
    if (typeof option === "object") {
      const value = option.value !== undefined ? option.value : option.label
      const label = option.label !== undefined ? option.label : value
      return { label: label, value: value }
    }
    return { label: String(option), value: option }
  })
}

function Select({ label, value, onChange, options, id, name }) {
  const generatedId = useId()
  const fieldId = id || "select-" + generatedId
  const items = normaliseOptions(options)
  const handleChange = typeof onChange === "function" ? onChange : noop

  const fallbackValue = items.length > 0 ? items[0].value : ""
  const current = value === undefined || value === null ? fallbackValue : value

  return (
    <div className="select">
      {label ? (
        <label className="select__label" htmlFor={fieldId}>
          {label}
        </label>
      ) : null}
      <div className="select__control">
        <select
          className="select__field"
          id={fieldId}
          name={name || fieldId}
          value={current}
          onChange={handleChange}
          aria-label={label ? undefined : "Select an option"}
        >
          {items.map(item => (
            <option key={String(item.value)} value={item.value}>
              {item.label}
            </option>
          ))}
        </select>
        <span className="select__chevron" aria-hidden="true">
          <svg viewBox="0 0 12 12" width="12" height="12" focusable="false" aria-hidden="true">
            <path
              d="M2.75 4.5 L6 7.75 L9.25 4.5"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </span>
      </div>
    </div>
  )
}

export default Select
