import React, { useMemo, useState } from "react"

/**
 * DataTable — the workhorse table for every scan, watchlist and screen.
 *
 * Built like a trading blotter rather than an admin grid: a sticky header,
 * mono right-aligned numerics, compact rows, and sorting that never reshuffles
 * equal values between renders.
 *
 * Props:
 *   columns       [{ key, header, align, numeric, sortable, width, render,
 *                    sortValue, headerTitle }]
 *   rows          array of row objects
 *   rowKey        (row) => string
 *   initialSort   { key, direction: "asc" | "desc" }
 *   onRowClick    optional (row) => void
 *   stickyHeader  boolean, default true
 *   minWidth      minimum table width in px, default 860
 *   emptyMessage  string shown when rows is empty
 *
 * SSR: the only state is the sort descriptor, so the server render and the
 * first client render produce identical markup.
 */

const ASC = "asc"
const DESC = "desc"
const EM_DASH = "—"
const GLYPH_ASC = "▲" /* up caret, ascending */
const GLYPH_DESC = "▼" /* down caret, descending */
const GLYPH_IDLE = "⇅" /* sortable, not currently sorted */
const INTERACTIVE = "a,button,input,select,textarea"

/* A value carrying no information sorts last, whichever way the column points. */
function isMissing(value) {
  if (value === null || value === undefined || value === "") return true
  if (typeof value === "number" && !Number.isFinite(value)) return true
  return false
}

/**
 * Numbers compare numerically, everything else as text. The "en" locale is
 * passed explicitly so Node and the browser agree and hydration stays clean.
 */
function compareValues(a, b) {
  if (typeof a === "number" && typeof b === "number") {
    return a < b ? -1 : a > b ? 1 : 0
  }
  if (typeof a === "boolean" || typeof b === "boolean") {
    return (a ? 1 : 0) - (b ? 1 : 0)
  }
  return String(a).localeCompare(String(b), "en")
}

function readSortValue(column, row) {
  if (typeof column.sortValue === "function") return column.sortValue(row)
  return row ? row[column.key] : undefined
}

function isSortable(column) {
  return column.sortable !== false
}

/* Numeric columns lean right unless the caller explicitly says otherwise. */
function alignsRight(column) {
  if (column.align === "right") return true
  if (column.align === "left") return false
  return Boolean(column.numeric)
}

function normaliseSort(initialSort, columns) {
  if (!initialSort || !initialSort.key) return null
  const column = columns.find(c => c.key === initialSort.key)
  if (!column || !isSortable(column)) return null
  return {
    key: initialSort.key,
    direction: initialSort.direction === ASC ? ASC : DESC,
  }
}

export default function DataTable({
  columns,
  rows,
  rowKey,
  initialSort,
  onRowClick,
  stickyHeader = true,
  minWidth = 860,
  emptyMessage = "No matching rows.",
}) {
  const cols = Array.isArray(columns) ? columns.filter(Boolean) : []
  const data = Array.isArray(rows) ? rows : []

  const [sort, setSort] = useState(() => normaliseSort(initialSort, cols))

  const sortedRows = useMemo(() => {
    if (!sort) return data
    const column = cols.find(c => c.key === sort.key)
    if (!column || !isSortable(column)) return data

    // Decorate with the original index so equal values keep their input order.
    // An explicit tie-break also survives a sortValue that collapses distinct
    // rows onto one key, which a merely "stable" sort would not guarantee.
    const decorated = data.map((row, index) => ({ row, index }))

    decorated.sort((a, b) => {
      const av = readSortValue(column, a.row)
      const bv = readSortValue(column, b.row)
      const aMissing = isMissing(av)
      const bMissing = isMissing(bv)

      if (aMissing && bMissing) return a.index - b.index
      if (aMissing) return 1
      if (bMissing) return -1

      const cmp = compareValues(av, bv)
      if (cmp !== 0) return sort.direction === ASC ? cmp : -cmp
      return a.index - b.index
    })

    return decorated.map(entry => entry.row)
  }, [data, cols, sort])

  function handleSort(column) {
    setSort(prev => {
      if (prev && prev.key === column.key) {
        return { key: column.key, direction: prev.direction === ASC ? DESC : ASC }
      }
      // First click on a measure shows the largest values; on a label, A to Z.
      return { key: column.key, direction: column.numeric ? DESC : ASC }
    })
  }

  const clickable = typeof onRowClick === "function"

  function handleRowClick(event, row) {
    const target = event.target
    if (target && typeof target.closest === "function") {
      const inner = target.closest(INTERACTIVE)
      if (inner && event.currentTarget.contains(inner)) return
    }
    onRowClick(row)
  }

  function handleRowKeyDown(event, row) {
    // Only the row itself activates; a control inside it keeps its own keys.
    if (event.target !== event.currentTarget) return
    if (event.key === "Enter") {
      event.preventDefault()
      onRowClick(row)
      return
    }
    if (event.key === " " || event.key === "Spacebar") {
      event.preventDefault() /* otherwise Space scrolls the page */
      onRowClick(row)
    }
  }

  if (cols.length === 0) return null

  const tableStyle = minWidth ? { minWidth: minWidth + "px" } : undefined
  // No class name exists for the sticky variant, so the one positional property
  // the prop actually controls is set here. Everything else stays with the CSS.
  const headStyle = stickyHeader ? { position: "sticky", top: 0 } : { position: "static" }

  return (
    <div className="dt__wrap">
      <table className="dt" style={tableStyle}>
        <thead>
          <tr>
            {cols.map(column => {
              const sortable = isSortable(column)
              const active = Boolean(sortable && sort && sort.key === column.key)
              const ariaSort = !sortable
                ? undefined
                : active
                ? sort.direction === ASC
                  ? "ascending"
                  : "descending"
                : "none"
              const classes = alignsRight(column) ? "dt__head dt__cell--right" : "dt__head"
              const style = column.width
                ? Object.assign({ width: column.width }, headStyle)
                : headStyle

              return (
                <th
                  key={column.key}
                  scope="col"
                  className={classes}
                  style={style}
                  aria-sort={ariaSort}
                >
                  {sortable ? (
                    <button
                      type="button"
                      className="dt__header-button"
                      title={column.headerTitle}
                      onClick={() => handleSort(column)}
                    >
                      {column.header}
                      <span
                        className={active ? "dt__sort dt__sort--" + sort.direction : "dt__sort"}
                        aria-hidden="true"
                      >
                        {active ? (sort.direction === ASC ? GLYPH_ASC : GLYPH_DESC) : GLYPH_IDLE}
                      </span>
                    </button>
                  ) : (
                    <span title={column.headerTitle}>{column.header}</span>
                  )}
                </th>
              )
            })}
          </tr>
        </thead>

        <tbody>
          {sortedRows.length === 0 ? (
            <tr className="dt__row">
              <td className="dt__empty" colSpan={cols.length}>
                {emptyMessage}
              </td>
            </tr>
          ) : (
            sortedRows.map((row, index) => {
              const key = typeof rowKey === "function" ? rowKey(row) : String(index)
              const rowProps = clickable
                ? {
                    className: "dt__row dt__row--clickable",
                    role: "button",
                    tabIndex: 0,
                    onClick: event => handleRowClick(event, row),
                    onKeyDown: event => handleRowKeyDown(event, row),
                  }
                : { className: "dt__row" }

              return (
                <tr key={key} {...rowProps}>
                  {cols.map(column => {
                    const cellClasses =
                      "dt__cell" +
                      (column.numeric ? " dt__cell--num" : "") +
                      (alignsRight(column) ? " dt__cell--right" : "")

                    let content
                    if (typeof column.render === "function") {
                      content = column.render(row)
                    } else {
                      const raw = row ? row[column.key] : undefined
                      content = isMissing(raw) ? EM_DASH : raw
                    }

                    return (
                      <td key={column.key} className={cellClasses}>
                        {content}
                      </td>
                    )
                  })}
                </tr>
              )
            })
          )}
        </tbody>
      </table>
    </div>
  )
}
